# Body plan of a cydippid ctenophore (Pleurobrachia). A: side view (oral pole down) from a Wikimedia
# template; B: aboral view generated by zoomorph, showing biradial symmetry (tentacular plane and the
# perpendicular sagittal plane of the flattened pharynx).
import wikibio as bio
from wikibio import zoomorph as zm
from wikibio import animalmorph as AM

P = bio.P
fig, ax = bio.canvas(31, 11.5)

bio.panel(ax, "A", (0.2, 11.3))
sp = AM.Specimen("wikimedia/ctenophore", at=(8.4, 5.6), height=9.6)
sp.draw(ax)
F = sp.frac
AM.callouts(ax, [(F(0.5, 0.965), "Apical organ (statocyst)", "right"),
                 (F(0.665, 0.62), "Meridional canal (beneath a comb row)", "right"),
                 (F(0.49, 0.68), "Pharynx", "right"),
                 (F(0.5, 0.345), "Mouth", "right"),
                 (F(0.43, 0.60), "Tentacle sheath", "right"),
                 (F(0.07, 0.45), "Tentacle with tentilla", "left")],
            left=2.4, right=15.3, gap=0.7)
bio.label(ax, (F(0.5, 1.0)[0], F(0.5, 1.0)[1] + 0.45), "Aboral pole", size="tiny", color=P.muted())
bio.label(ax, (F(0.5, 0.33)[0], F(0.5, 0.33)[1] - 0.35), "Oral pole", size="tiny", color=P.muted())

bio.panel(ax, "B", (20.4, 11.3))
c = (25.4, 5.6)
r = 3.2
a = zm.ctenophore(ax, c, r, angle=0.0)
zm.planes(ax, c, r, [0.0, 90.0])
bio.label(ax, (c[0] + r * 1.05, c[1] - 0.75), "Tentacular\nplane", size="tiny", color=P.muted(), ha="left")
bio.label(ax, (c[0], c[1] + r * 1.25), "Sagittal plane", size="tiny", color=P.muted())
bio.callout(ax, a["statocyst"], (c[0] - 0.9, c[1] - r - 0.9), "Statocyst", size="small")
bio.callout(ax, a["comb_row"], (c[0] + r + 0.5, c[1] + 2.4), "Comb row", size="small")
bio.callout(ax, a["pharynx"], (c[0] - 2.6, c[1] + r + 0.6), "Pharynx (beneath)", size="small")
bio.callout(ax, a["tentacle_sheath"], (c[0] + 2.4, c[1] - r - 0.9), "Tentacle sheath", size="small")
bio.label(ax, (c[0], 0.6), "Aboral view", size="small", color=P.muted())
